  "headline": "Propranolol hydrochloride is not on FDA's shortage list; both Corvale sites use product from Bryant Ranch Prepack (FEI 1000519407) which received an OAI inspection in 2009 and a Warning Letter in 2010, with the most recent inspection VAI on 2026-07-16",
  "headline_cites": ["D3", "E14", "E4", "E13", "E12"],
  "sentences": [
    {
      "text": "FDA's drug shortage list does not include propranolol hydrochloride as of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "Corvale East holds 92 tablets of the 40 mg presentation, providing 7.5 days of supply at 12.3 tablets per day.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale General holds 425 tablets of the same presentation, providing 29.3 days of supply at 14.5 tablets per day.",
      "cites": ["D2"]
    },
    {
      "text": "Both sites' inventory is labeled by Bryant Ranch Prepack (FEI 1000519407) per NDC 71335236909.",
      "cites": ["E1", "E2", "E14"]
    },
    {
      "text": "FDA inspection 590126 at that plant ended 2009-06-11 and was classified OAI, with the classification known on 2009-09-09.",
      "cites": ["E4"]
    },
    {
      "text": "A Warning Letter was issued to the same facility on 2010-04-08.",
      "cites": ["E13"]
    },
    {
      "text": "The most recent inspection (1326578) ended 2026-07-16 and was classified VAI, with the classification known on 2026-10-14.",
      "cites": ["E12"]
    }
  ]
}
